BASE='''<!doctype html><html lang=es><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>{% block t %}Colegio Dr. Agustín Cueva Tamariz{% endblock %}</title><link rel=stylesheet href=/static/style.css></head><body>{% block b %}{% endblock %}<script src=/static/app.js></script></body></html>'''
TOP='''<header class=top><div class=w><button id=mb data-toggle=nv aria-expanded=false aria-controls=nv>Menú</button><nav id=nv aria-label=Principal>
<a href="/#propuesta">Nosotros</a><a href="/#programas">Programas</a><a href=/preinscripcion>Admisión</a><a href="/#galeria">Galería</a><a href="/#noticias">Noticias</a><a href=/transferencia>Pagos</a><a href="/#contacto">Contacto</a><a href=/admin>Portal</a></nav>
<a class=badge href=/ aria-label=Inicio><img src=/static/logo.jpg alt="Escudo del colegio"></a></div></header>'''
INDEX='''{% extends "base" %}{% block b %}'''+TOP+'''
<div class=hero {% if hero %}style="background-image:linear-gradient(90deg,rgba(0,0,0,.25),transparent),url('/static-media/{{hero.file}}')"{% endif %}>{% if not hero %}<img class=mark src=/static/logo.jpg alt="">{% endif %}
<div class=panel><h1>{{ S('hero_title','Bienvenidos al Colegio Dr. Agustín Cueva Tamariz') }}</h1>{% if S('hero_text') %}<p>{{ S('hero_text') }}</p>{% endif %}
<a class=btn href=/preinscripcion>Inicia tu matrícula</a> {% if S('whatsapp') %}<a class="btn ghost" href="https://wa.me/{{ S('whatsapp')|replace('+','')|replace(' ','') }}" rel=noopener>WhatsApp</a>{% endif %}</div></div>
{% if programs %}<section id=programas class=soft><div class=w><h2>Programas educativos</h2><div class=g>{% for p in programs %}<div class=c><h3>{{p.name}}</h3><p><em>{{p.level}}</em></p><p>{{p.description}}</p>{% if p.subjects %}<p><small>{{p.subjects}}</small></p>{% endif %}<a class=btn href=/preinscripcion>Solicitar matrícula</a></div>{% endfor %}</div></div></section>{% endif %}
{% if prices %}<section id=valores><div class=w><h2>Valores vigentes</h2><div class=g>{% for p in prices %}<div class=c><h3>{{p.concept}}</h3><p><b>{{ money(p.amount_cents) }}</b><br><small>{{p.period}}{% if p.due %} · vence {{p.due}}{% endif %}</small></p></div>{% endfor %}</div></div></section>{% endif %}
{% if news %}<section id=noticias class=soft><div class=w><h2>Noticias y eventos</h2><div class=g>{% for n in news %}<div class=c><small>{{n.date}}</small><h3>{{n.title}}</h3><p>{{n.body}}</p></div>{% endfor %}</div></div></section>{% endif %}
{% if photos %}<section id=galeria><div class=w><h2>Galería</h2><div class=gal>{% for p in photos %}<img src="/static-media/{{p.file}}" alt="{{p.title}}{% if p.description %} — {{p.description}}{% endif %}" loading=lazy>{% endfor %}</div></div></section><dialog id=lb><img alt=""><p></p></dialog>{% endif %}
<section id=propuesta class=soft><div class=w><h2>Admisión</h2><p>Complete la preinscripción en línea. Recibirá un código para dar seguimiento. El colegio revisa cada solicitud y confirma la aceptación; enviar el formulario o pagar no la garantiza.</p><a class=btn href=/preinscripcion>Preinscribir estudiante</a> <a class=btn href=/transferencia>Registrar transferencia</a></div></section>
{% if S('phone') or S('email') or S('address') %}<section id=contacto><div class=w><h2>Contacto</h2>{% if S('address') %}<p>{{S('address')}}</p>{% endif %}{% if S('hours') %}<p>{{S('hours')}}</p>{% endif %}{% if S('phone') %}<p>Tel. {{S('phone')}}</p>{% endif %}{% if S('email') %}<p><a href="mailto:{{S('email')}}">{{S('email')}}</a></p>{% endif %}</div></section>{% endif %}
<footer><div class=w><p><strong>Unidad Educativa Particular Dr. Agustín Cueva Tamariz</strong></p><p>{% if S('facebook') %}<a href="{{S('facebook')}}" rel=noopener>Facebook</a> {% endif %}{% if S('instagram') %}<a href="{{S('instagram')}}" rel=noopener>Instagram</a>{% endif %}</p></div></footer>{% endblock %}'''
PRE='''{% extends "base" %}{% block b %}'''+TOP+'''<div class="w form"><h1>Preinscripción</h1>{% if errors %}<div class=err role=alert><ul>{% for e in errors %}<li>{{e}}</li>{% endfor %}</ul></div>{% endif %}
<form method=post>{{ csrf() }}<label>Nombre completo del estudiante<input name=student value="{{v.student}}" required></label><label>Fecha de nacimiento<input type=date name=birth value="{{v.birth}}" required></label>
<label>Nivel o programa<select name=level required><option value="">Seleccione</option>{% for p in progs %}<option>{{p.name}}</option>{% endfor %}</select></label>
<label>Nombre del representante legal<input name=guardian value="{{v.guardian}}" required></label><label>Correo electrónico<input type=email name=email value="{{v.email}}" required></label><label>Teléfono<input name=phone value="{{v.phone}}" required></label>
<label style="font-weight:400"><input type=checkbox name=consent style="width:auto"> Autorizo el tratamiento de estos datos para el proceso de admisión.</label><p><button class=btn>Enviar solicitud</button></p></form></div>{% endblock %}'''
THANKS='''{% extends "base" %}{% block b %}'''+TOP+'''<div class="w form"><h1>Solicitud recibida</h1><div class=ok>Su código de seguimiento es <b>{{code}}</b>. Guárdelo: lo necesitará para registrar pagos. Le enviamos una confirmación por correo.</div><p><a href=/>Volver al inicio</a></p></div>{% endblock %}'''
TRANSF='''{% extends "base" %}{% block b %}'''+TOP+'''<div class="w form"><h1>Registrar transferencia</h1>{% if S('bank_verified')=='1' and S('bank_info') %}<div class=c><b>Datos bancarios del colegio</b><br>{{S('bank_info')}}</div>{% endif %}
{% if msg %}<div class=ok role=status>{{msg}}</div>{% endif %}{% if err %}<div class=err role=alert>{{err}}</div>{% endif %}
<form method=post enctype=multipart/form-data>{{ csrf() }}<label>Código de la solicitud<input name=code required></label><label>Correo usado en la solicitud<input type=email name=email required></label><label>N.º de obligación (se lo indica el colegio)<input name=obl required></label><label>Referencia de la transferencia<input name=reference required></label><label>Comprobante (JPG, PNG o PDF)<input type=file name=file accept=".jpg,.jpeg,.png,.pdf"></label><p><button class=btn>Enviar comprobante</button></p></form></div>{% endblock %}'''
LOGIN='''{% extends "base" %}{% block b %}<div class="w form"><h1>Panel administrativo</h1>{% if err %}<div class=err role=alert>{{err}}</div>{% endif %}<form method=post>{{ csrf() }}<label>Correo<input type=email name=email required autocomplete=username></label><label>Contraseña<input type=password name=password required autocomplete=current-password></label><p><button class=btn>Ingresar</button></p></form><p><a href=/admin/olvide>Olvidé mi contraseña</a></p></div>{% endblock %}'''
FORGOT='''{% extends "base" %}{% block b %}<div class="w form"><h1>Recuperar contraseña</h1>{% if bad %}<div class=err>El enlace no es válido o venció.</div>{% endif %}{% if sent %}<div class=ok>Si el correo está autorizado, enviaremos un enlace.</div>{% else %}<form method=post>{{ csrf() }}<label>Correo<input type=email name=email required></label><p><button class=btn>Enviar enlace</button></p></form>{% endif %}</div>{% endblock %}'''
SETPW='''{% extends "base" %}{% block b %}<div class="w form"><h1>{{ 'Configurar acceso' if kind=='invite' else 'Nueva contraseña' }}</h1>{% if err %}<div class=err>{{err}}</div>{% endif %}<form method=post>{{ csrf() }}<label>Contraseña (10+ caracteres)<input type=password name=password required minlength=10 autocomplete=new-password></label><label>Repetir<input type=password name=password2 required minlength=10 autocomplete=new-password></label><p><button class=btn>Guardar</button></p></form></div>{% endblock %}'''
ADM='''{% extends "base" %}{% block b %}<div class=adm><aside class=side><b style=color:#fff>Panel</b><a href=/admin/panel>Inicio</a><a href=/admin/solicitudes>Solicitudes</a><a href=/admin/precios>Precios</a><a href=/admin/transferencias>Transferencias</a><a href=/admin/programas>Programas</a><a href=/admin/noticias>Noticias</a><a href=/admin/fotos>Fotos</a><a href=/admin/ajustes>Ajustes</a><a href=/admin/admins>Administradores</a><form method=post action=/admin/salir>{{ csrf() }}<button class=btn style=margin-top:1rem>Salir</button></form></aside><main class=main>
{% if err %}<div class=err>{{err}}</div>{% endif %}
{% if page=='panel' %}<h1>Inicio</h1><div class=k><div><b>{{st.nuevas}}</b>Solicitudes nuevas</div><div><b>{{st.revision}}</b>En revisión</div><div><b>{{st.pend}}</b>Transferencias por revisar</div><div><b>{{st.venc}}</b>Obligaciones vencidas</div><div><b>{{money(st.ing)}}</b>Ingresos confirmados</div></div><h3>Actividad reciente</h3><table>{% for a in st.act %}<tr><td>{{a.ts}}</td><td>{{a.who}}</td><td>{{a.action}}</td></tr>{% endfor %}</table>
{% elif page=='apps' %}<h1>Solicitudes</h1><form class=row>Estado <select name=s><option value="">Todos</option>{% for x in STAT %}<option {{'selected' if x==s}}>{{x}}</option>{% endfor %}</select> <input name=t value="{{t}}" placeholder="Nombre o código"><button class=btn>Filtrar</button></form>
<table><tr><th>Código</th><th>Estudiante</th><th>Nivel</th><th>Contacto</th><th>Estado</th><th>Obligaciones</th></tr>{% for r in rows %}<tr><td>{{r.code}}</td><td>{{r.student}}<br><small>{{r.birth}}</small></td><td>{{r.level}}</td><td>{{r.guardian}}<br>{{r.email}}<br>{{r.phone}}</td><td><form method=post action=/admin/solicitud/{{r.id}}>{{ csrf() }}<select name=status>{% for x in STAT %}<option {{'selected' if x==r.status}}>{{x}}</option>{% endfor %}</select><textarea name=notes rows=2 placeholder="Observaciones internas">{{r.notes}}</textarea><button class=btn>Guardar</button></form></td><td>{% for o in obls if o.app_id==r.id %}#{{o.id}} {{o.concept}} {{money(o.amount_cents)}} ({{o.status}})<br>{% endfor %}<form method=post action=/admin/solicitud/{{r.id}}/obligacion class=row>{{ csrf() }}<select name=price>{% for p in prices %}<option value={{p.id}}>{{p.concept}} {{money(p.amount_cents)}}</option>{% endfor %}</select><button class=btn>Generar</button></form></td></tr>{% endfor %}</table>
{% elif page=='prices' %}<h1>Precios</h1><p>Los cambios no alteran obligaciones ni pagos ya generados.</p><table><tr><th>Concepto</th><th>Período</th><th>Importe USD</th><th>Vence</th><th>Activo</th><th></th></tr>{% for r in rows %}<tr><form method=post>{{ csrf() }}<input type=hidden name=id value={{r.id}}><td><input name=concept value="{{r.concept}}"></td><td><input name=period value="{{r.period}}"></td><td><input name=amount value="{{'%.2f'|format(r.amount_cents/100)}}"></td><td><input type=date name=due value="{{r.due}}"></td><td><input type=checkbox name=active {{'checked' if r.active}}></td><td><button class=btn>Guardar</button></td></form></tr>{% endfor %}
<tr><form method=post>{{ csrf() }}<td><input name=concept placeholder="Concepto" required></td><td><input name=period placeholder="Período"></td><td><input name=amount placeholder="0.00" required></td><td><input type=date name=due></td><td></td><td><button class=btn>Agregar</button></td></form></tr></table><h3>Historial de cambios</h3><table>{% for h in hist %}<tr><td>{{h.ts}}</td><td>{{h.concept}}</td><td>{{money(h.old_cents)}} → {{money(h.new_cents)}}</td><td>{{h.by_user}}</td></tr>{% endfor %}</table>
{% elif page=='crud' %}<h1>{{sec|capitalize}}</h1><form method=post>{{ csrf() }}{% for c in cols %}<label>{{c}}{% if c=='date' %}<input type=date name=date>{% elif c in('description','body','subjects') %}<textarea name={{c}} rows=3></textarea>{% else %}<input name={{c}} required>{% endif %}</label>{% endfor %}<p><button class=btn>Agregar</button></p></form><table>{% for r in rows %}<tr><td>{{r[1]}}</td><td><form method=post>{{ csrf() }}<button name=del value={{r.id}}>Eliminar</button></form></td></tr>{% endfor %}</table>
{% elif page=='fotos' %}<h1>Fotos</h1><p>Categoría «Portada» define la imagen principal. Publique solo fotos con autorización.</p><form method=post enctype=multipart/form-data>{{ csrf() }}<label>Archivo<input type=file name=file required></label><label>Título<input name=title></label><label>Descripción<input name=description></label><label>Categoría<input name=category></label><label>Orden<input name=sort type=number value=0></label><p><button class=btn>Subir</button></p></form><table>{% for r in rows %}<tr><td><img src="/static-media/{{r.file}}" width=80 alt=""></td><td>{{r.title}}<br>{{r.category}}</td><td><form method=post>{{ csrf() }}<button name=del value={{r.id}}>Eliminar</button></form></td></tr>{% endfor %}</table>
{% elif page=='transf' %}<h1>Transferencias</h1><table><tr><th>Estudiante</th><th>Concepto</th><th>Importe</th><th>Referencia</th><th>Estado</th><th></th></tr>{% for r in rows %}<tr><td>{{r.student}}</td><td>{{r.concept}}</td><td>{{money(r.amount_cents)}}</td><td>{{r.reference}}{% if r.file %}<br><a href=/admin/comprobante/{{r.id}}>Ver comprobante</a>{% endif %}</td><td>{{r.status}}{% if r.reason %}<br>{{r.reason}}{% endif %}{% if r.reviewer %}<br><small>{{r.reviewer}} {{r.reviewed}}</small>{% endif %}</td><td>{% if r.status=='pendiente' %}<form method=post class=row>{{ csrf() }}<input type=hidden name=id value={{r.id}}><button class=btn name=act value=ok>Aprobar (dinero recibido)</button><input name=reason placeholder="Motivo de rechazo"><button name=act value=no>Rechazar</button></form>{% endif %}</td></tr>{% endfor %}</table>
{% elif page=='admins' %}<h1>Administradores</h1>{% if link %}<div class=ok>Correo no configurado. Enlace de invitación: {{link}}</div>{% endif %}<form method=post class=row>{{ csrf() }}<input type=email name=email placeholder="Correo" required><select name=role><option value=owner>Administrador principal</option><option value=secretaria>Secretaría</option><option value=finanzas>Personal financiero</option></select><button class=btn>Invitar</button></form><table>{% for r in rows %}<tr><td>{{r.email}}</td><td>{{r.role}}</td></tr>{% endfor %}</table>
{% elif page=='set' %}<h1>Ajustes</h1><form method=post>{{ csrf() }}{% for k in K %}<label>{{k}}<input name={{k}} value="{{S(k)}}"></label>{% endfor %}<p>bank_verified = 1 publica los datos bancarios en la web.</p><button class=btn>Guardar</button></form>{% endif %}
</main></div>{% endblock %}'''
T={'base':BASE,'index.html':INDEX,'pre.html':PRE,'thanks.html':THANKS,'transf.html':TRANSF,'login.html':LOGIN,'forgot.html':FORGOT,'setpw.html':SETPW,'adm.html':ADM}
